CREATE OR REPLACE FUNCTION analytics.apply_approved_indexes()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'analytics', 'public'
AS $function$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM analytics.approved_indexes WHERE applied_at IS NULL LOOP
    EXECUTE r.suggested_index; -- expect CREATE INDEX CONCURRENTLY ...;
    UPDATE analytics.approved_indexes SET applied_at = now() WHERE id = r.id;
  END LOOP;
END$function$

CREATE OR REPLACE FUNCTION analytics.exec_sql(q text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'analytics', 'pg_temp'
AS $function$
DECLARE
  stmt text := q;
  lowered text := lower(q);
  res jsonb;
BEGIN
  -- Block mutation statements
  IF lowered ~ '\b(insert|update|delete|drop|alter|truncate|grant|revoke|create|refresh materialized view)\b' THEN
    RAISE EXCEPTION 'Mutation statements are not allowed';
  END IF;

  -- Allow only selects from analytics schema
  IF lowered NOT LIKE 'select % from analytics.%' AND lowered NOT LIKE 'with % select % from analytics.%' THEN
    RAISE EXCEPTION 'Only SELECTs from analytics schema are permitted';
  END IF;

  EXECUTE format('SELECT coalesce(jsonb_agg(t), ''[]''::jsonb) FROM (%s) t', stmt) INTO res;
  RETURN res;
END;
$function$

CREATE OR REPLACE FUNCTION analytics.purge_old_index_usage(p_keep_days integer DEFAULT 30)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'analytics', 'public', 'pg_temp'
AS $function$
DECLARE v_count int;
BEGIN
  DELETE FROM analytics.index_usage_snapshots
  WHERE captured_at < now() - make_interval(days => p_keep_days);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION app_private.api_keys_encrypt_secret()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.secret IS NOT NULL THEN
    NEW.secret_enc := app_private.encrypt_text(NEW.secret);
    NEW.secret := '***';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION app_private.apply_org_rls_for_org(table_schema text, table_name text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  execute format('alter table %I.%I enable row level security', table_schema, table_name);
  perform 1 from pg_policies where schemaname=table_schema and tablename=table_name and policyname in ('Org read','Org write','Org update','Org delete');
  if found then
    execute format('drop policy if exists "Org read" on %I.%I', table_schema, table_name);
    execute format('drop policy if exists "Org write" on %I.%I', table_schema, table_name);
    execute format('drop policy if exists "Org update" on %I.%I', table_schema, table_name);
    execute format('drop policy if exists "Org delete" on %I.%I', table_schema, table_name);
  end if;
  execute format('grant select, insert, update, delete on %I.%I to authenticated', table_schema, table_name);
  execute format('create policy "Org read" on %I.%I for select to authenticated using (org_id in (select public.get_user_org_ids()))', table_schema, table_name);
  execute format('create policy "Org write" on %I.%I for insert to authenticated with check (org_id in (select public.get_user_org_ids()))', table_schema, table_name);
  execute format('create policy "Org update" on %I.%I for update to authenticated using (org_id in (select public.get_user_org_ids())) with check (org_id in (select public.get_user_org_ids()))', table_schema, table_name);
  execute format('create policy "Org delete" on %I.%I for delete to authenticated using (org_id in (select public.get_user_org_ids()))', table_schema, table_name);
end; $function$

CREATE OR REPLACE FUNCTION app_private.apply_org_rls_for_tenant(table_schema text, table_name text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  execute format('alter table %I.%I enable row level security', table_schema, table_name);
  -- drop existing org policies if present
  perform 1 from pg_policies where schemaname=table_schema and tablename=table_name and policyname in ('Org read','Org write','Org update','Org delete');
  if found then
    execute format('drop policy if exists "Org read" on %I.%I', table_schema, table_name);
    execute format('drop policy if exists "Org write" on %I.%I', table_schema, table_name);
    execute format('drop policy if exists "Org update" on %I.%I', table_schema, table_name);
    execute format('drop policy if exists "Org delete" on %I.%I', table_schema, table_name);
  end if;
  -- grants
  execute format('grant select, insert, update, delete on %I.%I to authenticated', table_schema, table_name);
  -- create org-based policies using tenant_id
  execute format('create policy "Org read" on %I.%I for select to authenticated using (tenant_id in (select public.get_user_org_ids()))', table_schema, table_name);
  execute format('create policy "Org write" on %I.%I for insert to authenticated with check (tenant_id in (select public.get_user_org_ids()))', table_schema, table_name);
  execute format('create policy "Org update" on %I.%I for update to authenticated using (tenant_id in (select public.get_user_org_ids())) with check (tenant_id in (select public.get_user_org_ids()))', table_schema, table_name);
  execute format('create policy "Org delete" on %I.%I for delete to authenticated using (tenant_id in (select public.get_user_org_ids()))', table_schema, table_name);
end; $function$

CREATE OR REPLACE FUNCTION app_private.audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'app_private', 'public', 'pg_catalog'
AS $function$
DECLARE
  v_row jsonb;
  v_tenant uuid;
BEGIN
  v_row := to_jsonb(COALESCE(NEW, OLD));
  v_tenant := (v_row ->> 'tenant_id')::uuid;
  INSERT INTO public.audit_logs(tenant_id, event, user_id, metadata)
  VALUES (v_tenant, TG_OP || ' ' || TG_TABLE_NAME, (SELECT auth.uid()), v_row);
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION app_private.get_current_tenant_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE COST 10
 SET search_path TO 'app_private', 'pg_catalog'
AS $function$
DECLARE
  v_uid uuid;
  v_tenant uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth.uid() is NULL. Ensure a valid JWT is set.' USING ERRCODE = '28000';
  END IF;

  SELECT tm.tenant_id
    INTO v_tenant
  FROM public.tenant_memberships AS tm
  WHERE tm.user_id = v_uid
    AND tm.is_default IS TRUE
  LIMIT 1;

  IF v_tenant IS NULL THEN
    -- Fallback to latest membership if no default flagged
    SELECT tm2.tenant_id
      INTO v_tenant
    FROM public.tenant_memberships AS tm2
    WHERE tm2.user_id = v_uid
    ORDER BY tm2.is_default DESC, tm2.created_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'No tenant membership found for user %', v_uid USING ERRCODE = '02000';
  END IF;

  RETURN v_tenant;
END
$function$

CREATE OR REPLACE FUNCTION app_private.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION checks.assert_no_null_tenant_rows()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'checks', 'public'
AS $function$
DECLARE r record; v_sql text; v_cnt bigint;
BEGIN
  FOR r IN SELECT table_name FROM checks.tenant_tables LOOP
    v_sql := format('SELECT count(*) FROM public.%I WHERE tenant_id IS NULL', r.table_name);
    EXECUTE v_sql INTO v_cnt;
    IF v_cnt > 0 THEN
      PERFORM checks.log_alert(format('Found %s rows with NULL tenant_id in %s', v_cnt, r.table_name));
    END IF;
  END LOOP;
END$function$

CREATE OR REPLACE FUNCTION checks.assert_rls_enabled()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'checks', 'public'
AS $function$
DECLARE r record; enabled bool;
BEGIN
  FOR r IN SELECT table_name FROM checks.tenant_tables LOOP
    SELECT relrowsecurity INTO enabled FROM pg_class c WHERE c.relname = r.table_name AND c.relnamespace = 'public'::regnamespace;
    IF NOT COALESCE(enabled, false) THEN
      PERFORM checks.log_alert(format('RLS disabled on %s', r.table_name));
    END IF;
  END LOOP;
END$function$

CREATE OR REPLACE FUNCTION checks.assert_tenant_id_indexed()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'checks', 'public'
AS $function$
DECLARE r record; v_cnt int;
BEGIN
  FOR r IN SELECT table_name FROM checks.tenant_tables LOOP
    SELECT count(*) INTO v_cnt
    FROM pg_indexes
    WHERE schemaname='public' AND tablename=r.table_name AND indexdef ILIKE '%(tenant_id%';
    IF v_cnt = 0 THEN
      PERFORM checks.log_alert(format('Missing tenant_id index on %s', r.table_name));
    END IF;
  END LOOP;
END$function$

CREATE OR REPLACE FUNCTION checks.log_alert(msg text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'checks', 'public'
AS $function$
DECLARE sql text;
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema='public' AND table_name='error_logs'
  ) THEN
    sql := 'INSERT INTO public.error_logs(tenant_id, message, severity, context, resolved) ' ||
           'VALUES (NULL, %L, ''alert'', jsonb_build_object(''component'',''checks''), false)';
    EXECUTE format(sql, msg);
  END IF;
END$function$

CREATE OR REPLACE FUNCTION checks.run_all()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'checks', 'public'
AS $function$
BEGIN
  PERFORM checks.assert_no_null_tenant_rows();
  PERFORM checks.assert_tenant_id_indexed();
  PERFORM checks.assert_rls_enabled();
END$function$

CREATE OR REPLACE FUNCTION dbdev.install(package_name text, base_url text DEFAULT 'https://api.database.dev/rest/v1/'::text, api_key text DEFAULT 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InhtdXB0cHBsZnZpaWZyYndtbXR2Iiwicm9sZSI6ImFub24iLCJpYXQiOjE2ODAxMDczNzIsImV4cCI6MTk5NTY4MzM3Mn0.z2CN0mvO2No8wSi46Gw59DFGCTJrzM0AQKsu_5k134s'::text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
declare
    http_ext_schema regnamespace = extnamespace::regnamespace from pg_catalog.pg_extension where extname = 'http' limit 1;
    pgtle_is_available bool = true from pg_catalog.pg_extension where extname = 'pg_tle' limit 1;
    -- HTTP respones
    rec jsonb;
    status int;
    contents json;

    -- Install Record
    rec_sql text;
    rec_ver text;
    rec_from_ver text;
    rec_to_ver text;
    rec_description text;
    rec_requires text[];
    rec_default_ver text;
begin

    if http_ext_schema is null then
        raise exception using errcode='22000', message=format('dbdev requires the http extension and it is not available');
    end if;

    if pgtle_is_available is null then
        raise exception using errcode='22000', message=format('dbdev requires the pgtle extension and it is not available');
    end if;

    -------------------
    -- Base Versions --
    -------------------
    execute  $stmt$select row_to_json(x)
    from $stmt$ || pg_catalog.quote_ident(http_ext_schema::text) || $stmt$.http(
        (
            'GET',
            format(
                '%spackage_versions?select=version,sql,control_description,control_requires&limit=50&or=(package_name.eq.%s,package_alias.eq.%s)',
                $stmt$ || pg_catalog.quote_literal(base_url) || $stmt$,
                $stmt$ || pg_catalog.quote_literal(package_name) || $stmt$,
                $stmt$ || pg_catalog.quote_literal(package_name) || $stmt$
            ),
            array[
                ('apiKey', $stmt$ || pg_catalog.quote_literal(api_key) || $stmt$)::http_header
            ],
            null,
            null
        )
    ) x
    limit 1; $stmt$
    into rec;

    status = (rec ->> 'status')::int;
    contents = to_json(rec ->> 'content') #>> '{}';

    if status <> 200 then
        raise notice using errcode='22000', message=format('DBDEV INFO: %s', contents);
        raise exception using errcode='22000', message=format('Non-200 response code while loading versions from dbdev');
    end if;

    if contents is null or json_typeof(contents) <> 'array' or json_array_length(contents) = 0 then
        raise exception using errcode='22000', message=format('No versions found for package named %s', package_name);
    end if;

    for rec_ver, rec_sql, rec_description, rec_requires in select
            (r ->> 'version'),
            (r ->> 'sql'),
            (r ->> 'control_description'),
            array(select json_array_elements_text((r -> 'control_requires')))
        from
            json_array_elements(contents) as r
        loop

        -- Install the primary version
        if not exists (
            select true
            from pgtle.available_extensions()
            where
                name = package_name
        ) then
            perform pgtle.install_extension(package_name, rec_ver, rec_description, rec_sql, rec_requires);
        end if;

        -- Install other available versions
        if not exists (
            select true
            from pgtle.available_extension_versions()
            where
                name = package_name
                and version = rec_ver
        ) then
            perform pgtle.install_extension_version_sql(package_name, rec_ver, rec_sql);
        end if;

    end loop;

    ----------------------
    -- Upgrade Versions --
    ----------------------
    execute  $stmt$select row_to_json(x)
    from $stmt$ || pg_catalog.quote_ident(http_ext_schema::text) || $stmt$.http(
        (
            'GET',
            format(
                '%spackage_upgrades?select=from_version,to_version,sql&limit=50&or=(package_name.eq.%s,package_alias.eq.%s)',
                $stmt$ || pg_catalog.quote_literal(base_url) || $stmt$,
                $stmt$ || pg_catalog.quote_literal(package_name) || $stmt$,
                $stmt$ || pg_catalog.quote_literal(package_name) || $stmt$
            ),
            array[
                ('apiKey', $stmt$ || pg_catalog.quote_literal(api_key) || $stmt$)::http_header
            ],
            null,
            null
        )
    ) x
    limit 1; $stmt$
    into rec;

    status = (rec ->> 'status')::int;
    contents = to_json(rec ->> 'content') #>> '{}';

    if status <> 200 then
        raise notice using errcode='22000', message=format('DBDEV INFO: %s', contents);
        raise exception using errcode='22000', message=format('Non-200 response code while loading upgrade paths from dbdev');
    end if;

    if json_typeof(contents) <> 'array' then
        raise exception using errcode='22000', message=format('Invalid response from dbdev upgrade paths');
    end if;

    for rec_from_ver, rec_to_ver, rec_sql in select
            (r ->> 'from_version'),
            (r ->> 'to_version'),
            (r ->> 'sql')
        from
            json_array_elements(contents) as r
        loop

        if not exists (
            select true
            from pgtle.extension_update_paths(package_name)
            where
                source = rec_from_ver
                and target = rec_to_ver
                and path is not null
        ) then
            perform pgtle.install_update_path(package_name, rec_from_ver, rec_to_ver, rec_sql);
        end if;
    end loop;

    -------------------------
    -- Set Default Version --
    -------------------------
    execute  $stmt$select row_to_json(x)
    from $stmt$ || pg_catalog.quote_ident(http_ext_schema::text) || $stmt$.http(
        (
            'GET',
            format(
                '%spackages?select=default_version&limit=1&or=(package_name.eq.%s,package_alias.eq.%s)',
                $stmt$ || pg_catalog.quote_literal(base_url) || $stmt$,
                $stmt$ || pg_catalog.quote_literal(package_name) || $stmt$,
                $stmt$ || pg_catalog.quote_literal(package_name) || $stmt$
            ),
            array[
                ('apiKey', $stmt$ || pg_catalog.quote_literal(api_key) || $stmt$)::http_header
            ],
            null,
            null
        )
    ) x
    limit 1; $stmt$
    into rec;

    status = (rec ->> 'status')::int;
    contents = to_json(rec ->> 'content') #>> '{}';

    if status <> 200 then
        raise notice using errcode='22000', message=format('DBDEV INFO: %s', contents);
        raise exception using errcode='22000', message=format('Non-200 response code while loading packages from dbdev');
    end if;

    if contents is null or json_typeof(contents) <> 'array' or json_array_length(contents) = 0 then
        raise exception using errcode='22000', message=format('No package named %s found', package_name);
    end if;

    for rec_default_ver in select
            (r ->> 'default_version')
        from
            json_array_elements(contents) as r
        loop

        if rec_default_ver is not null then
            perform pgtle.set_default_version(package_name, rec_default_ver);
        else
            raise notice using errcode='22000', message=format('DBDEV INFO: missing default version');
        end if;

    end loop;

    --------------------------
    -- Send Download Notice --
    --------------------------
    -- Notifies dbdev that a package has been downloaded and records IP + user agent so we can compute unique download counts
    execute  $stmt$select row_to_json(x)
    from $stmt$ || pg_catalog.quote_ident(http_ext_schema::text) || $stmt$.http(
        (
            'POST',
            format(
                '%srpc/register_download',
                $stmt$ || pg_catalog.quote_literal(base_url) || $stmt$
            ),
            array[
                ('apiKey', $stmt$ || pg_catalog.quote_literal(api_key) || $stmt$)::http_header,
                ('x-client-info', 'dbdev/0.0.5')::http_header
            ],
            'application/json',
            json_build_object('package_name', $stmt$ || pg_catalog.quote_literal(package_name) || $stmt$)::text
        )
    ) x
    limit 1; $stmt$
    into rec;

    return true;
end;
$function$

CREATE OR REPLACE FUNCTION extensions.grant_pg_cron_access()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
    revoke trigger on cron.job_run_details from postgres;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION extensions.grant_pg_graphql_access()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    if not exists (
        select 1
        from pg_catalog.pg_event_trigger_ddl_commands() ev
        join pg_catalog.pg_extension e on ev.objid = e.oid
        where e.extname = 'pg_graphql'
    ) then
        return;
    end if;

    drop function if exists graphql_public.graphql;
    create or replace function graphql_public.graphql(
        "operationName" text default null,
        query text default null,
        variables jsonb default null,
        extensions jsonb default null
    )
        returns jsonb
        language sql
    as $$
        select graphql.resolve(
            query := query,
            variables := coalesce(variables, '{}'),
            "operationName" := "operationName",
            extensions := extensions
        );
    $$;

    -- Attach the wrapper to the extension so DROP EXTENSION cascades to it,
    -- which in turn triggers set_graphql_placeholder to reinstall the "not enabled" stub.
    alter extension pg_graphql add function graphql_public.graphql(text, text, jsonb, jsonb);

    grant usage on schema graphql to postgres, anon, authenticated, service_role;
    grant execute on function graphql.resolve to postgres, anon, authenticated, service_role;
    grant usage on schema graphql to postgres with grant option;
    grant usage on schema graphql_public to postgres with grant option;
end;
$function$

CREATE OR REPLACE FUNCTION extensions.grant_pg_net_access()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_roles
      WHERE rolname = 'supabase_functions_admin'
    )
    THEN
      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;
    END IF;

    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    IF EXISTS (
      SELECT FROM pg_extension
      WHERE extname = 'pg_net'
      -- all versions in use on existing projects as of 2025-02-20
      -- version 0.12.0 onwards don't need these applied
      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8.0', '0.10.0', '0.11.0')
    ) THEN
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION extensions.index_advisor(query text)
 RETURNS TABLE(startup_cost_before jsonb, startup_cost_after jsonb, total_cost_before jsonb, total_cost_after jsonb, index_statements text[], errors text[])
 LANGUAGE plpgsql
AS $function$
declare
    n_args int;
    prepared_statement_name text = 'index_advisor_working_statement';
    hypopg_schema_name text = (select extnamespace::regnamespace::text from pg_extension where extname = 'hypopg');
    explain_plan_statement text;
    error_message text;
    rec record;
    plan_initial jsonb;
    plan_final jsonb;
    statements text[] = '{}';
begin

    -- Remove comment lines (its common that they contain semicolons)
    query := trim(
        regexp_replace(
            regexp_replace(
                regexp_replace(query,'\/\*.+\*\/', '', 'g'),
            '--[^\r\n]*', ' ', 'g'),
        '\s+', ' ', 'g')
    );

    -- Remove trailing semicolon
    query := regexp_replace(query, ';\s*$', '');

    begin
        -- Disallow multiple statements
        if query ilike '%;%' then
            raise exception 'Query must not contain a semicolon';
        end if;

        -- Hack to support PostgREST because the prepared statement for args incorrectly defaults to text
        query := replace(query, 'WITH pgrst_payload AS (SELECT $1 AS json_data)', 'WITH pgrst_payload AS (SELECT $1::json AS json_data)');

        -- Create a prepared statement for the given query
        deallocate all;
        execute format('prepare %I as %s', prepared_statement_name, query);

        -- Detect how many arguments are present in the prepared statement
        n_args = (
            select
                coalesce(array_length(parameter_types, 1), 0)
            from
                pg_prepared_statements
            where
                name = prepared_statement_name
            limit
                1
        );

        -- Create a SQL statement that can be executed to collect the explain plan
        explain_plan_statement = format(
            'set local plan_cache_mode = force_generic_plan; explain (format json) execute %I%s',
            --'explain (format json) execute %I%s',
            prepared_statement_name,
            case
                when n_args = 0 then ''
                else format(
                    '(%s)', array_to_string(array_fill('null'::text, array[n_args]), ',')
                )
            end
        );

        -- Store the query plan before any new indexes
        execute explain_plan_statement into plan_initial;

        -- Create possible indexes
        for rec in (
            with extension_regclass as (
                select
                    distinct objid as oid
                from
                    pg_catalog.pg_depend
                where
                    deptype = 'e'
            )
            select
                pc.relnamespace::regnamespace::text as schema_name,
                pc.relname as table_name,
                pa.attname as column_name,
                format(
                    'select %I.hypopg_create_index($i$create index on %I.%I(%I)$i$)',
                    hypopg_schema_name,
                    pc.relnamespace::regnamespace::text,
                    pc.relname,
                    pa.attname
                ) hypopg_statement
            from
                pg_catalog.pg_class pc
                join pg_catalog.pg_attribute pa
                    on pc.oid = pa.attrelid
                left join extension_regclass er
                    on pc.oid = er.oid
                left join pg_catalog.pg_index pi
                    on pc.oid = pi.indrelid
                    and (select array_agg(x) from unnest(pi.indkey) v(x)) = array[pa.attnum]
                    and pi.indexprs is null -- ignore expression indexes
                    and pi.indpred is null -- ignore partial indexes
            where
                pc.relnamespace::regnamespace::text not in ( -- ignore schema list
                    'pg_catalog', 'pg_toast', 'information_schema'
                )
                and er.oid is null -- ignore entities owned by extensions
                and pc.relkind in ('r', 'm') -- regular tables, and materialized views
                and pc.relpersistence = 'p' -- permanent tables (not unlogged or temporary)
                and pa.attnum > 0
                and not pa.attisdropped
                and pi.indrelid is null
                and pa.atttypid in (20,16,1082,1184,1114,701,23,21,700,1083,2950,1700,25,18,1042,1043)
            )
            loop
                -- Create the hypothetical index
                execute rec.hypopg_statement;
            end loop;

        /*
        for rec in select * from hypopg()
            loop
                raise notice '%', rec;
            end loop;
        */

        -- Create a prepared statement for the given query
        -- The original prepared statement MUST be dropped because its plan is cached
        execute format('deallocate %I', prepared_statement_name);
        execute format('prepare %I as %s', prepared_statement_name, query);

        -- Store the query plan after new indexes
        execute explain_plan_statement into plan_final;

        --raise notice '%', plan_final;

        -- Idenfity referenced indexes in new plan
        execute format(
            'select
                coalesce(array_agg(hypopg_get_indexdef(indexrelid) order by indrelid, indkey::text), $i${}$i$::text[])
            from
                %I.hypopg()
            where
                %s ilike ($i$%%$i$ || indexname || $i$%%$i$)
            ',
            hypopg_schema_name,
            quote_literal(plan_final)::text
        ) into statements;

        -- Reset all hypothetical indexes
        perform hypopg_reset();

        -- Reset prepared statements
        deallocate all;

        return query values (
            (plan_initial -> 0 -> 'Plan' -> 'Startup Cost'),
            (plan_final -> 0 -> 'Plan' -> 'Startup Cost'),
            (plan_initial -> 0 -> 'Plan' -> 'Total Cost'),
            (plan_final -> 0 -> 'Plan' -> 'Total Cost'),
            statements::text[],
            array[]::text[]
        );
        return;

    exception when others then
        get stacked diagnostics error_message = MESSAGE_TEXT;

        return query values (
            null::jsonb,
            null::jsonb,
            null::jsonb,
            null::jsonb,
            array[]::text[],
            array[error_message]::text[]
        );
        return;
    end;

end;
$function$

CREATE OR REPLACE FUNCTION extensions.set_graphql_placeholder()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
            set search_path to ''
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$function$

