CREATE OR REPLACE FUNCTION public.compute_audit_notarization_hash(max_rows integer DEFAULT 5000)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  computed_hash text;
BEGIN
  IF max_rows < 1 THEN
    max_rows := 1;
  END IF;

  IF to_regclass('public.audit_logs') IS NULL THEN
    RETURN md5('');
  END IF;

  SELECT md5(COALESCE(string_agg(to_jsonb(a)::text, '|' ORDER BY a.id::text), ''))
  INTO computed_hash
  FROM (
    SELECT *
    FROM public.audit_logs
    ORDER BY id DESC
    LIMIT max_rows
  ) a;

  RETURN computed_hash;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_membership_invite(p_tenant_id uuid, p_user_id uuid, p_role text DEFAULT 'viewer'::text, p_expires_in_minutes integer DEFAULT 10080)
 RETURNS memberships
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_token text;
  v_row public.memberships;
BEGIN
  IF NOT app_private.is_tenant_admin(p_tenant_id) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  IF p_role NOT IN ('owner','admin','editor','viewer') THEN
    RAISE EXCEPTION 'invalid role %', p_role;
  END IF;
  v_token := encode(gen_random_bytes(24), 'hex');
  INSERT INTO public.memberships (tenant_id, user_id, role, status, invited_by, invite_token, invite_expires_at)
  VALUES (p_tenant_id, p_user_id, p_role, 'invited', (SELECT auth.uid()), v_token, NOW() + make_interval(mins => p_expires_in_minutes))
  ON CONFLICT (tenant_id, user_id) DO UPDATE
    SET role = EXCLUDED.role,
        status = 'invited',
        invited_by = (SELECT auth.uid()),
        invite_token = EXCLUDED.invite_token,
        invite_expires_at = EXCLUDED.invite_expires_at,
        updated_at = NOW()
  RETURNING * INTO v_row;
  RETURN v_row;
END;$function$

CREATE OR REPLACE FUNCTION public.create_table_record(table_name text, payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  id uuid := gen_random_uuid();
  cols text;
  vals text;
  sql text;
  result uuid;
BEGIN
  SELECT string_agg(format('%I', key), ',') FROM jsonb_object_keys(payload) AS key INTO cols;
  SELECT string_agg(format('$1->>%L', key), ',') FROM jsonb_object_keys(payload) AS key INTO vals;
  sql := format('INSERT INTO %I (id, %s) VALUES ($2, %s) RETURNING id', table_name, cols, vals);
  EXECUTE sql INTO result USING payload, id;
  RETURN result;
END;$function$

CREATE OR REPLACE FUNCTION public.create_table_record(p_table_schema text, p_table_name text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_table_name TEXT;
  v_query TEXT;
  v_result JSONB;
  v_keys TEXT[];
  v_values TEXT[];
BEGIN
  IF p_table_schema != 'public' THEN
    RAISE EXCEPTION 'Only public schema tables are allowed';
  END IF;

  IF p_table_name NOT IN (
    'receipt_uploads', 'receipts', 'receipt_items',
    'recon_jobs', 'recon_results', 'recon_templates',
    'feature_flags', 'feature_flag_environments', 'feature_flag_overrides',
    'webhooks', 'webhook_deliveries',
    'api_keys', 'idempotency_keys',
    'usage_events', 'usage_counters',
    'ingestion_sources', 'ingestions', 'raw_records', 'normalized_transactions',
    'reconciliation_runs', 'reconciliation_matches', 'exports'
  ) THEN
    RAISE EXCEPTION 'Table % is not accessible for writes via this function', p_table_name;
  END IF;

  v_table_name := quote_ident(p_table_schema) || '.' || quote_ident(p_table_name);

  SELECT array_agg(key), array_agg(quote_literal(value))
  INTO v_keys, v_values
  FROM jsonb_each_text(p_data);

  v_query := format(
    'INSERT INTO %s (%s) VALUES (%s) RETURNING row_to_json(%s.*)',
    v_table_name,
    array_to_string(v_keys, ', '),
    array_to_string(v_values, ', '),
    quote_ident(p_table_name)
  );

  EXECUTE v_query INTO v_result;
  RETURN v_result;
END;$function$

