CREATE OR REPLACE FUNCTION public.ensure_check_constraint(p_schema text, p_table text, p_constraint text, p_sql text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NOT public.table_exists(p_schema, p_table) THEN
    RETURN;
  END IF;

  IF public.constraint_exists(p_schema, p_table, p_constraint) THEN
    RETURN;
  END IF;

  EXECUTE p_sql;
EXCEPTION
  WHEN others THEN
    RAISE NOTICE 'Skipping check constraint % due to error: %', p_constraint, SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_column(p_schema text, p_table text, p_column text, p_type text, p_default text DEFAULT NULL::text, p_not_null boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  ddl text;
BEGIN
  IF public.table_exists(p_schema, p_table) AND NOT public.column_exists(p_schema, p_table, p_column) THEN
    ddl := format('ALTER TABLE %I.%I ADD COLUMN %I %s', p_schema, p_table, p_column, p_type);
    EXECUTE ddl;

    IF p_default IS NOT NULL THEN
      EXECUTE format('ALTER TABLE %I.%I ALTER COLUMN %I SET DEFAULT %s', p_schema, p_table, p_column, p_default);
    END IF;

    IF p_not_null THEN
      BEGIN
        EXECUTE format('ALTER TABLE %I.%I ALTER COLUMN %I SET NOT NULL', p_schema, p_table, p_column);
      EXCEPTION
        WHEN others THEN
          RAISE NOTICE 'Could not set NOT NULL for %.%.%: %', p_schema, p_table, p_column, SQLERRM;
      END;
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_fk(p_schema text, p_table text, p_constraint text, p_fk_sql text, p_required_local_columns text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  col text;
BEGIN
  IF NOT public.table_exists(p_schema, p_table) THEN
    RAISE NOTICE 'Skipping FK %, table %.% does not exist', p_constraint, p_schema, p_table;
    RETURN;
  END IF;

  IF public.constraint_exists(p_schema, p_table, p_constraint) THEN
    RETURN;
  END IF;

  IF p_required_local_columns IS NOT NULL THEN
    FOREACH col IN ARRAY p_required_local_columns LOOP
      IF NOT public.column_exists(p_schema, p_table, col) THEN
        RAISE NOTICE 'Skipping FK % because %.%.% is missing', p_constraint, p_schema, p_table, col;
        RETURN;
      END IF;
    END LOOP;
  END IF;

  EXECUTE p_fk_sql;
EXCEPTION
  WHEN others THEN
    RAISE NOTICE 'Skipping FK % due to error: %', p_constraint, SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_idempotency(_tenant uuid, _key text, _ttl_minutes integer DEFAULT 5)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  exists_active boolean;
BEGIN
  -- deny if an active key exists
  SELECT EXISTS (
    SELECT 1 FROM public.idempotency_keys
    WHERE tenant_id = _tenant AND key = _key AND (expires_at IS NULL OR expires_at > now())
  ) INTO exists_active;
  IF exists_active THEN
    RETURN false;
  END IF;

  -- insert or refresh
  INSERT INTO public.idempotency_keys(id, tenant_id, key, created_at, expires_at)
  VALUES (gen_random_uuid(), _tenant, _key, now(), now() + make_interval(mins => _ttl_minutes))
  ON CONFLICT DO NOTHING;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_index(p_schema text, p_table text, p_index text, p_index_sql text, p_required_columns text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  missing_col text;
BEGIN
  IF NOT public.table_exists(p_schema, p_table) THEN
