CREATE OR REPLACE FUNCTION public.evaluate_slos()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'public'
AS $function$
DECLARE w interval; v_start timestamptz; v_end timestamptz; target float8; obs float8;
BEGIN
  IF EXISTS (SELECT 1 FROM public.service_slos WHERE key='webhook_success_rate') THEN
    SELECT slo_window, target INTO w, target FROM public.service_slos WHERE key='webhook_success_rate';
    v_end := now(); v_start := v_end - w;
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='webhook_attempts') THEN
      IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='webhook_attempts' AND column_name='status') THEN
        EXECUTE format('SELECT CASE WHEN count(*)=0 THEN 1.0 ELSE avg((status=%L)::int)::float8 END FROM public.webhook_attempts WHERE created_at BETWEEN %L AND %L', 'success', v_start, v_end) INTO obs;
      ELSE
        obs := 1.0;
      END IF;
      IF obs < target THEN
        INSERT INTO public.slo_breaches(slo_key, observed, window_start, window_end)
        VALUES ('webhook_success_rate', obs, v_start, v_end);
        PERFORM checks.log_alert(format('SLO breach webhook_success_rate: %.4f < target %.4f', obs, target));
      END IF;
    END IF;
  END IF;
END$function$

CREATE OR REPLACE FUNCTION public.execute_recommendation(p_recommendation_id uuid, p_executed_by uuid, p_action_taken text, p_outcome_notes text DEFAULT NULL::text)
