 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_action_id UUID;
  v_insight_id UUID;
BEGIN
  SELECT insight_id INTO v_insight_id FROM public.ops_recommendations WHERE id = p_recommendation_id;

  INSERT INTO public.ops_actions (
