CREATE OR REPLACE FUNCTION public.get_table_records(p_table_schema text, p_table_name text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_filters jsonb DEFAULT '{}'::jsonb, p_order_by text DEFAULT 'created_at'::text, p_order_asc boolean DEFAULT false)
 RETURNS TABLE(data jsonb, total_count bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_table_name TEXT;
  v_query TEXT;
  v_count_query TEXT;
  v_filter_query TEXT := '';
  v_key TEXT;
  v_value TEXT;
BEGIN
  IF p_table_schema != 'public' THEN
    RAISE EXCEPTION 'Only public schema tables are allowed';
  END IF;

  IF p_table_name NOT IN (
    'receipt_uploads', 'receipts', 'receipt_items',
    'recon_jobs', 'recon_results', 'recon_templates', 'recon_audits', 'recon_runs',
    'mapping_templates', 'transform_recipes', 'validation_rules', 'contract_versions',
    'drift_events', 'workflow_runs',
    'feature_flags', 'feature_flag_environments', 'feature_flag_overrides',
    'webhooks', 'webhook_deliveries',
    'api_keys', 'idempotency_keys',
    'usage_events', 'usage_aggregate_daily', 'usage_counters',
    'billing_accounts', 'subscriptions', 'add_ons', 'add_on_purchases',
    'ingestion_sources', 'ingestions', 'raw_records', 'normalized_transactions',
    'reconciliation_runs', 'reconciliation_matches', 'exports'
  ) THEN
    RAISE EXCEPTION 'Table % is not accessible via this function', p_table_name;
  END IF;

  v_table_name := quote_ident(p_table_schema) || '.' || quote_ident(p_table_name);

  FOR v_key, v_value IN SELECT * FROM jsonb_each_text(p_filters)
  LOOP
    IF v_filter_query = '' THEN
      v_filter_query := ' WHERE ' || quote_ident(v_key) || ' = ' || quote_literal(v_value);
    ELSE
      v_filter_query := v_filter_query || ' AND ' || quote_ident(v_key) || ' = ' || quote_literal(v_value);
    END IF;
  END LOOP;

  v_count_query := 'SELECT COUNT(*) FROM ' || v_table_name || v_filter_query;
  EXECUTE v_count_query INTO total_count;

  v_query := format(
    'SELECT jsonb_agg(row_to_json(t)) FROM (
      SELECT * FROM %s %s ORDER BY %I %s LIMIT %s OFFSET %s
    ) t',
    v_table_name,
    v_filter_query,
    p_order_by,
    CASE WHEN p_order_asc THEN 'ASC' ELSE 'DESC' END,
    p_limit,
    p_offset
  );

  EXECUTE v_query INTO data;
  RETURN;
END;$function$

CREATE OR REPLACE FUNCTION public.get_user_org_ids()
 RETURNS SETOF uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare col_exists boolean; begin
  select exists (select 1 from information_schema.columns where table_schema='public' and table_name='user_organizations' and column_name='org_id') into col_exists;
  if col_exists then
    return query select org_id from public.user_organizations where user_id = (select auth.uid());
    return; end if;
  select exists (select 1 from information_schema.columns where table_schema='public' and table_name='user_organizations' and column_name='organization_id') into col_exists;
  if col_exists then
    return query select organization_id from public.user_organizations where user_id = (select auth.uid());
    return; end if;
  select exists (select 1 from information_schema.columns where table_schema='public' and table_name='user_organizations' and column_name='tenant_id') into col_exists;
  if col_exists then
    return query select tenant_id from public.user_organizations where user_id = (select auth.uid());
    return; end if;
  raise exception 'user_organizations must contain org_id/organization_id/tenant_id';
end; $function$

CREATE OR REPLACE FUNCTION public.has_plan_or_higher(p_user_id uuid, p_required_plan text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_billing_account_id UUID;
  v_user_plan TEXT;
  v_plan_hierarchy JSONB := '{"free": 0, "starter": 1, "growth": 2, "scale": 3, "enterprise": 4, "base": 1, "pro": 2}'::JSONB;
  v_user_level INTEGER;
  v_required_level INTEGER;
BEGIN
  -- Get billing account
  SELECT id INTO v_billing_account_id
  FROM public.billing_accounts
  WHERE user_id = p_user_id
    AND status = 'active'
    AND deleted_at IS NULL
  LIMIT 1;

  IF v_billing_account_id IS NULL THEN
    RETURN FALSE;
  END IF;

  -- Get user's plan
  SELECT plan_id INTO v_user_plan
  FROM public.subscriptions
  WHERE billing_account_id = v_billing_account_id
    AND status IN ('active', 'trialing')
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_user_plan IS NULL THEN
    RETURN FALSE;
  END IF;

  -- Check plan hierarchy
  v_user_level := COALESCE((v_plan_hierarchy->>v_user_plan)::INTEGER, 0);
  v_required_level := COALESCE((v_plan_hierarchy->>p_required_plan)::INTEGER, 0);

  RETURN v_user_level >= v_required_level;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_tenant_member(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID;
  v_is_member BOOLEAN := false;
BEGIN
  -- Get current user ID
  v_user_id := current_user_id();

  -- If no user ID, return false
  IF v_user_id IS NULL THEN
    RETURN false;
  END IF;

  -- Check if user is member of tenant
  SELECT EXISTS (
    SELECT 1 FROM tenant_users
    WHERE tenant_id = p_tenant_id
      AND user_id = v_user_id
  ) INTO v_is_member;

  RETURN COALESCE(v_is_member, false);
END;
$function$

