CREATE OR REPLACE FUNCTION public.log_audit_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_api_key_id uuid := nullif(auth.jwt() ->> 'api_key_id', '')::uuid;
  v_ip text := nullif(auth.jwt() ->> 'ip', '');
  v_user_agent text := nullif(auth.jwt() ->> 'user_agent', '');
  v_tenant_id uuid := coalesce(new.tenant_id, old.tenant_id, public.current_tenant_id());
  v_event text := tg_op;
  v_payload jsonb;
begin
  if tg_op = 'INSERT' then
    v_payload := to_jsonb(new);
  elsif tg_op = 'UPDATE' then
    v_payload := jsonb_build_object('old', to_jsonb(old), 'new', to_jsonb(new));
  else
    v_payload := to_jsonb(old);
  end if;

  insert into public.audit_logs (tenant_id, event, user_id, api_key_id, ip, user_agent, metadata, timestamp)
  values (
    v_tenant_id,
    tg_table_schema || '.' || tg_table_name || ':' || v_event,
    v_user_id,
    v_api_key_id,
    v_ip,
    v_user_agent,
    jsonb_build_object('row', v_payload),
    now()
  );

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_job_result(p_job_id uuid, p_ok boolean, p_error jsonb DEFAULT NULL::jsonb, p_retry_in_seconds integer DEFAULT 0)
 RETURNS jobs
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_job public.jobs%ROWTYPE;
  v_max int;
BEGIN
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'job % not found', p_job_id;
  END IF;

  v_max := COALESCE(v_job.max_attempts, 8);

  IF p_ok THEN
    UPDATE public.jobs
    SET status = 'succeeded', locked_at = NULL, locked_by = NULL, last_error = NULL, updated_at = now()
    WHERE id = p_job_id
    RETURNING * INTO v_job;
  ELSE
    IF v_job.attempts >= v_max THEN
      UPDATE public.jobs
      SET status = 'dead', locked_at = NULL, locked_by = NULL, last_error = p_error, updated_at = now()
      WHERE id = p_job_id
      RETURNING * INTO v_job;
    ELSE
      UPDATE public.jobs
      SET status = 'queued', available_at = now() + make_interval(secs => GREATEST(1, p_retry_in_seconds)),
          locked_at = NULL, locked_by = NULL, last_error = p_error, updated_at = now()
      WHERE id = p_job_id
      RETURNING * INTO v_job;
    END IF;
  END IF;

  RETURN v_job;
END;
$function$

CREATE OR REPLACE FUNCTION public.match_page_sections(embedding vector, match_threshold double precision, match_count integer, min_content_length integer)
 RETURNS TABLE(id bigint, page_id bigint, slug text, heading text, content text, similarity double precision)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_variable
begin
  return query
  select
    public.nods_page_section.id,
    public.nods_page_section.page_id,
    public.nods_page_section.slug,
    public.nods_page_section.heading,
    public.nods_page_section.content,
    (public.nods_page_section.embedding <#> embedding) * -1 as similarity
  from public.nods_page_section

  where length(public.nods_page_section.content) >= min_content_length
  and (public.nods_page_section.embedding <#> embedding) * -1 > match_threshold
  order by public.nods_page_section.embedding <#> embedding
  limit match_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.messages_broadcast_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'public'
AS $function$
DECLARE v_topic text; v_tenant uuid; v_row jsonb;
BEGIN
  v_tenant := COALESCE(NEW.tenant_id, OLD.tenant_id);
  v_topic := 'room:' || COALESCE(NEW.conversation_id, OLD.conversation_id)::text || ':messages';

  -- increment per-tenant usage window
  PERFORM public.realtime_increment(v_tenant);

  -- choose row to send
  v_row := to_jsonb(COALESCE(NEW, OLD));

  -- broadcast database change via recommended helper
  PERFORM realtime.broadcast_changes(
    v_topic,
    TG_OP,
    TG_OP,
    TG_TABLE_NAME,
    TG_TABLE_SCHEMA,
    NEW,
    OLD
  );
  RETURN COALESCE(NEW, OLD);
END$function$

