CREATE OR REPLACE FUNCTION public.truncate_old_partitions_before(p_cutoff_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_min_date date := (now()::date - 7);
  r record;
BEGIN
  IF p_cutoff_date > v_min_date THEN
    RAISE EXCEPTION 'Cutoff % is too recent. Minimum retention is 7 days.', p_cutoff_date;
  END IF;

  FOR r IN
    SELECT inhrelid::regclass AS child
    FROM pg_inherits
    JOIN pg_class parent ON pg_inherits.inhparent = parent.oid
    JOIN pg_namespace nsp ON parent.relnamespace = nsp.oid
    WHERE nsp.nspname='public' AND parent.relname IN ('api_call_logs','http_logs')
  LOOP
    -- Derive partition date from name suffix assuming daily partitions like table_yyyymmdd
    -- If format differs, this will skip safely.
    BEGIN
      PERFORM 1 FROM (
        SELECT to_date(substring(relname from '(\d{8})$'), 'YYYYMMDD') AS part_date
        FROM pg_class WHERE oid = r.child::regclass
      ) d WHERE d.part_date IS NOT NULL AND d.part_date < p_cutoff_date;

      IF FOUND THEN
        EXECUTE format('DROP TABLE IF EXISTS %s;', r.child);
      END IF;
    EXCEPTION WHEN others THEN
      -- ignore partitions not matching naming convention
      NULL;
    END;
  END LOOP;
END; $function$

