CREATE OR REPLACE FUNCTION public.update_table_record(table_name text, record_id uuid, patch jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  cols text[];
  sets text;
  sql text;
BEGIN
  SELECT array_agg(format('%I = COALESCE($1->>%L, %I)', a.attname, a.attname, a.attname))
    INTO cols
  FROM pg_catalog.pg_attribute a
  JOIN pg_catalog.pg_class c ON a.attrelid = c.oid
  JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relname = table_name AND a.attnum > 0 AND NOT a.attisdropped;

  sets := array_to_string(cols, ', ');
  sql := format('UPDATE %I SET %s WHERE id = $2', table_name, sets);
  EXECUTE sql USING patch, record_id;
END;$function$

CREATE OR REPLACE FUNCTION public.update_table_record(p_table_schema text, p_table_name text, p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_table_name TEXT;
  v_query TEXT;
  v_result JSONB;
  v_set_clause TEXT := '';
  v_key TEXT;
BEGIN
  IF p_table_schema != 'public' THEN
    RAISE EXCEPTION 'Only public schema tables are allowed';
  END IF;

  IF p_table_name NOT IN (
    'receipt_uploads', 'receipts', 'receipt_items',
    'recon_jobs', 'recon_results', 'recon_templates',
    'feature_flags', 'feature_flag_environments', 'feature_flag_overrides',
    'webhooks', 'webhook_deliveries',
    'api_keys', 'idempotency_keys',
    'usage_events', 'usage_counters',
    'ingestion_sources', 'ingestions', 'raw_records', 'normalized_transactions',
    'reconciliation_runs', 'reconciliation_matches', 'exports'
  ) THEN
    RAISE EXCEPTION 'Table % is not accessible for updates via this function', p_table_name;
  END IF;

  v_table_name := quote_ident(p_table_schema) || '.' || quote_ident(p_table_name);

  FOR v_key IN SELECT jsonb_object_keys(p_data)
  LOOP
    IF v_set_clause = '' THEN
      v_set_clause := quote_ident(v_key) || ' = ' || quote_literal(p_data->>v_key);
    ELSE
      v_set_clause := v_set_clause || ', ' || quote_ident(v_key) || ' = ' || quote_literal(p_data->>v_key);
    END IF;
  END LOOP;

  v_query := format(
    'UPDATE %s SET %s WHERE id = %L RETURNING row_to_json(%s.*)',
    v_table_name,
    v_set_clause,
    p_id,
    quote_ident(p_table_name)
  );

  EXECUTE v_query INTO v_result;
  RETURN v_result;
END;$function$

