CREATE OR REPLACE FUNCTION public.validate_usage_event_server_side(p_billing_account_id uuid, p_event_type character varying, p_integration_id character varying DEFAULT NULL::character varying, p_add_on_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$
DECLARE
  v_billing_account RECORD;
  v_subscription RECORD;
  v_add_on_purchase RECORD;
BEGIN
  -- Ownership: only the billing account owner (or an admin) may validate it.
  SELECT * INTO v_billing_account
  FROM billing_accounts
  WHERE id = p_billing_account_id
    AND status = 'active'
    AND deleted_at IS NULL
    AND (user_id = auth.uid() OR COALESCE(is_admin(), false));

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  SELECT * INTO v_subscription
  FROM subscriptions
  WHERE billing_account_id = p_billing_account_id
    AND status = 'active'
    AND current_period_end > NOW()
  ORDER BY created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    SELECT * INTO v_subscription
    FROM subscriptions
    WHERE billing_account_id = p_billing_account_id
      AND status = 'trialing'
      AND trial_end > NOW()
    ORDER BY created_at DESC
    LIMIT 1;

    IF NOT FOUND THEN
      RETURN false;
    END IF;
  END IF;

  IF p_add_on_id IS NOT NULL THEN
    SELECT * INTO v_add_on_purchase
    FROM add_on_purchases
    WHERE billing_account_id = p_billing_account_id
      AND add_on_id = p_add_on_id
      AND status = 'active';

    IF NOT FOUND THEN
      RETURN false;
    END IF;
  END IF;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.webhook_attempts_backoff()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'public'
AS $function$
BEGIN
  NEW.attempts := COALESCE(NEW.attempts, 0) + 1;
  IF NEW.attempts >= 3 THEN
    NEW.next_attempt_at := now() + (interval '5 minutes' * POWER(2, NEW.attempts-3));
  END IF;
  RETURN NEW;
END$function$

